final class UserConsentPurposesUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new UserConsentPurposes(
            uid: 'one',
            user: new UserRef('one'),
            consentPurpose: new ConsentPurposeRef('one'),
            granted: true,
            decisionAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            ipAddress: 'one',
            userAgent: 'one',
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = UserConsentPurposes::calculatedFields();

        // @Assert
        $this->assertEquals([], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getConsentPurpose(), $other->getConsentPurpose());
        $this->assertTrue($one->isConsentPurposeChanged());
        $this->assertEquals($one->isGranted(), $other->isGranted());
        $this->assertTrue($one->isGrantedChanged());
        $this->assertEquals($one->getDecisionAt(), $other->getDecisionAt());
        $this->assertTrue($one->isDecisionAtChanged());
        $this->assertEquals($one->getIpAddress(), $other->getIpAddress());
        $this->assertTrue($one->isIpAddressChanged());
        $this->assertEquals($one->getUserAgent(), $other->getUserAgent());
        $this->assertTrue($one->isUserAgentChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
