    public function test_json_compare(): void
    {
        // @Arrange
        $one = new UserConsentPurposes(
            uid: 'one',
            user: new UserRef('one'),
            consentPurpose: new ConsentPurposeRef('one'),
            granted: true,
            decisionAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            ipAddress: 'one',
            userAgent: 'one',
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['user']['$ref']);
        $this->assertEquals('one', $json['consentPurpose']['$ref']);
        $this->assertEquals(true, $json['granted']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['decisionAt']);
        $this->assertEquals('one', $json['ipAddress']);
        $this->assertEquals('one', $json['userAgent']);
        $this->assertEquals(1, $json['version']);
    }
